<?php require_once __DIR__.'/../config/conexao.php';verificarAcesso('admin');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){validarCsrf();$act=$_POST['acao']??'';try{if($act==='produto'){if(!empty($_POST['id']))db()->prepare('UPDATE produtos SET id_categoria=?,nome=?,tipo_medida=?,preco_unitario=?,estoque_qtd=?,imagem_url=?,ativo=? WHERE id_produto=?')->execute([(int)$_POST['categoria'],trim($_POST['nome']),$_POST['tipo'],(float)$_POST['preco'],(float)$_POST['estoque'],trim($_POST['imagem']),isset($_POST['ativo'])?1:0,(int)$_POST['id']]);else db()->prepare('INSERT INTO produtos(id_categoria,nome,tipo_medida,preco_unitario,estoque_qtd,imagem_url) VALUES(?,?,?,?,?,?)')->execute([(int)$_POST['categoria'],trim($_POST['nome']),$_POST['tipo'],(float)$_POST['preco'],(float)$_POST['estoque'],trim($_POST['imagem'])]);$msg='Produto salvo.';}elseif($act==='equipe'){$p=$_POST['perfil'];if(!in_array($p,['cliente','admin','separador','entregador','visitante'],true))throw new RuntimeException();db()->prepare('INSERT INTO usuarios(nome,email,senha,perfil,telefone) VALUES(?,?,?,?,?)')->execute([trim($_POST['nome']),trim($_POST['email']),password_hash($_POST['senha'],PASSWORD_DEFAULT),$p,trim($_POST['telefone'])]);$msg='Conta criada.';}elseif($act==='cupom'){$code=strtoupper(trim($_POST['codigo']??''));$title=trim($_POST['titulo']??'');$description=trim($_POST['descricao']??'');$type=$_POST['tipo']??'';$value=(float)($_POST['valor']??0);$minimum=(float)($_POST['pedido_minimo']??0);$validity=trim($_POST['validade']??'')?:null;$limit=trim($_POST['limite_usos']??'')===''?null:(int)$_POST['limite_usos'];if(!preg_match('/^[A-Z0-9_-]{3,40}$/',$code)||$title===''||!in_array($type,['percentual','fixo'],true)||$value<=0||($type==='percentual'&&$value>100)||$minimum<0||($limit!==null&&$limit<1))throw new RuntimeException();if($validity){$validityDate=DateTime::createFromFormat('!Y-m-d',$validity);$validityErrors=DateTime::getLastErrors();if(!$validityDate||$validityDate->format('Y-m-d')!==$validity||($validityErrors&&($validityErrors['warning_count']||$validityErrors['error_count'])))throw new RuntimeException();}db()->prepare('INSERT INTO cupons(codigo,titulo,descricao,tipo,valor,pedido_minimo,validade,limite_usos) VALUES(?,?,?,?,?,?,?,?)')->execute([$code,$title,$description,$type,$value,$minimum,$validity,$limit]);$msg='Cupom criado e disponível para clientes.';}
elseif($act==='config'){$lat=filter_var($_POST['loja_latitude']??null,FILTER_VALIDATE_FLOAT);$lon=filter_var($_POST['loja_longitude']??null,FILTER_VALIDATE_FLOAT);if($lat===false||$lat < -90||$lat > 90||$lon===false||$lon < -180||$lon > 180)throw new RuntimeException('Invalid store coordinates.');foreach(['frete_padrao','loja_latitude','loja_longitude'] as $k){$v=trim($_POST[$k]??'');db()->prepare('INSERT INTO configuracoes(chave,valor) VALUES(?,?) ON DUPLICATE KEY UPDATE valor=VALUES(valor)')->execute([$k,$v]);}$msg='Configuração atualizada.';}elseif($act==='schedule_config'){$days=trim($_POST['agendamento_dias']??'');$dayParts=array_values(array_unique(array_filter(array_map('intval',explode(',',$days)),static fn($day)=>$day>=1&&$day<=7)));$deliverySlots=array_values(array_filter(array_map('trim',preg_split('/\R/',trim($_POST['entrega_horarios']??'')))));$pickupSlots=array_values(array_filter(array_map('trim',preg_split('/\R/',trim($_POST['retirada_horarios']??'')))));if(!$dayParts||!$deliverySlots||!$pickupSlots)throw new RuntimeException('Informe os dias e as faixas de horário para entrega e retirada.');foreach(array_merge($deliverySlots,$pickupSlots) as $slot){if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d-(?:[01]\d|2[0-3]):[0-5]\d$/',$slot)||substr($slot,0,5)>=substr($slot,6,5))throw new RuntimeException('Use faixas no formato 09:00-10:00, com início anterior ao fim.');}foreach(['agendamento_dias'=>implode(',',$dayParts),'entrega_horarios'=>implode(PHP_EOL,$deliverySlots),'retirada_horarios'=>implode(PHP_EOL,$pickupSlots)] as $key=>$value){db()->prepare('INSERT INTO configuracoes(chave,valor) VALUES(?,?) ON DUPLICATE KEY UPDATE valor=VALUES(valor)')->execute([$key,$value]);}$msg='Horários de entrega agendada e retirada atualizados.';}elseif($act==='cancelar'){$orderId=(int)$_POST['pedido'];$q=db()->prepare("SELECT id_cupom FROM pedidos WHERE id_pedido=? AND status IN ('pendente','em_separacao','aguardando_aprovacao')");$q->execute([$orderId]);$couponId=$q->fetchColumn();$q=db()->prepare("UPDATE pedidos SET status='cancelado' WHERE id_pedido=? AND status IN ('pendente','em_separacao','aguardando_aprovacao')");$q->execute([$orderId]);if($q->rowCount()&&$couponId){db()->prepare('UPDATE cupons_clientes SET id_pedido=NULL,usado_em=NULL WHERE id_cupom=? AND id_pedido=?')->execute([(int)$couponId,$orderId]);db()->prepare('UPDATE cupons SET usos=GREATEST(usos-1,0) WHERE id_cupom=?')->execute([(int)$couponId]);}$msg='Pedido cancelado quando elegível.';}}catch(Throwable $e){$msg='Não foi possível salvar. Verifique os dados informados.';}}$cats=db()->query('SELECT * FROM categorias')->fetchAll();$products=db()->query('SELECT p.*,c.nome categoria FROM produtos p JOIN categorias c USING(id_categoria) ORDER BY p.nome')->fetchAll();$users=db()->query("SELECT id_usuario,nome,email,perfil FROM usuarios WHERE perfil IN ('cliente','admin','separador','entregador','visitante') ORDER BY perfil,nome")->fetchAll();$orders=db()->query('SELECT p.*,u.nome cliente FROM pedidos p JOIN usuarios u ON u.id_usuario=p.id_cliente ORDER BY p.data_criacao DESC LIMIT 100')->fetchAll();$cfg=db()->query('SELECT chave,valor FROM configuracoes')->fetchAll(PDO::FETCH_KEY_PAIR);$coupons=db()->query('SELECT * FROM cupons ORDER BY data_criacao DESC')->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administração · Alvorada</title><link rel="stylesheet" href="/assets/css/style.css"></head><body><main class="container"><div class="section-head"><h1>Painel administrativo</h1><a class="button light" href="#cupons">Cupons</a></div><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><section class="card"><h2>Novo produto</h2><form method="post" class="form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="acao" value="produto"><div class="form-row"><label>Nome<input name="nome" required></label><label>Categoria<select name="categoria"><?php foreach($cats as $c):?><option value="<?=$c['id_categoria']?>"><?=h($c['nome'])?></option><?php endforeach;?></select></label></div><div class="form-row"><label>Unidade<select name="tipo"><option>UN</option><option>KG</option></select></label><label>Preço<input name="preco" type="number" min="0" step=".01" required></label></div><div class="form-row"><label>Estoque<input name="estoque" type="number" min="0" step=".001" required></label><label>URL da imagem<input name="imagem" type="url"></label></div><button>Adicionar produto</button></form></section><section class="card"><h2>Catálogo (<?=count($products)?>)</h2><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Categoria</th><th>Medida</th><th>Preço</th><th>Estoque</th><th>Ativo</th><th>Salvar</th></tr></thead><tbody><?php foreach($products as $p):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="acao" value="produto"><input type="hidden" name="id" value="<?=$p['id_produto']?>"><td><input name="nome" value="<?=h($p['nome'])?>"></td><td><select name="categoria"><?php foreach($cats as $c):?><option value="<?=$c['id_categoria']?>" <?=$c['id_categoria']==$p['id_categoria']?'selected':''?>><?=h($c['nome'])?></option><?php endforeach;?></select></td><td><select name="tipo"><option <?=$p['tipo_medida']==='UN'?'selected':''?>>UN</option><option <?=$p['tipo_medida']==='KG'?'selected':''?>>KG</option></select></td><td><input name="preco" type="number" step=".01" value="<?=$p['preco_unitario']?>"></td><td><input name="estoque" type="number" step=".001" value="<?=$p['estoque_qtd']?>"></td><td><input type="checkbox" name="ativo" <?=$p['ativo']?'checked':''?>></td><td><input type="hidden" name="imagem" value="<?=h($p['imagem_url']??'')?>"><button>Salvar</button></td></form></tr><?php endforeach;?></tbody></table></div></section><section class="card"><h2>Contas e perfis</h2><form method="post" class="form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="acao" value="equipe"><div class="form-row"><label>Nome<input name="nome" required></label><label>E-mail<input name="email" type="email" required></label></div><div class="form-row"><label>Senha inicial<input name="senha" type="password" minlength="8" required></label><label>Perfil<select name="perfil"><option value="cliente">Cliente</option><option value="admin">Administrador</option><option value="separador">Separador</option><option value="entregador">Entregador</option><option value="visitante">Visitante</option></select></label></div><label>Telefone<input name="telefone"></label><button>Criar conta da equipe</button></form><ul><?php foreach($users as $u):?><li><?=h($u['nome'].' · '.$u['email'].' · '.$u['perfil'])?></li><?php endforeach;?></ul></section><section class="card"><h2>Entrega em raio de 20 km</h2><form method="post" class="form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="acao" value="config"><label>Frete base da entrega agendada (R$)<input name="frete_padrao" type="number" min="0" step=".01" value="<?=h($cfg['frete_padrao']??'5.00')?>"></label><p>Entregas expressas e agendadas disponíveis até 20 km do ponto configurado abaixo. Acima disso, somente retirada grátis.</p><div class="form-row"><label>Latitude da loja<input name="loja_latitude" type="number" min="-90" max="90" step=".000001" value="<?=h($cfg['loja_latitude']??'-23.55052')?>" required></label><label>Longitude da loja<input name="loja_longitude" type="number" min="-180" max="180" step=".000001" value="<?=h($cfg['loja_longitude']??'-46.63331')?>" required></label></div><p class="muted">Ajuste as coordenadas para o endereço exato do mercado. O valor inicial aponta para a região central de São Paulo.</p><button>Salvar configuração</button></form></section><section class="card"><h2>Disponibilidade de entrega agendada e retirada</h2><form method="post" class="form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="acao" value="schedule_config"><label>Dias disponíveis (1=segunda, 7=domingo)<input name="agendamento_dias" value="<?=h($cfg['agendamento_dias']??'1,2,3,4,5,6')?>" placeholder="1,2,3,4,5,6" required></label><label>Horários específicos para entrega agendada, uma faixa por linha<textarea name="entrega_horarios" rows="5" required><?=h($cfg['entrega_horarios']??"09:00-10:00\n10:00-11:00\n11:00-12:00\n14:00-15:00\n15:00-16:00\n16:00-17:00\n17:00-18:00")?></textarea></label><label>Horários disponíveis para retirada, uma faixa por linha<textarea name="retirada_horarios" rows="3" required><?=h($cfg['retirada_horarios']??"09:00-12:00\n14:00-18:00")?></textarea></label><p class="muted">Use faixas como 14:00-15:00. O cliente escolhe uma data nos próximos 30 dias e vê somente os horários definidos para a modalidade.</p><button>Salvar horários disponíveis</button></form></section><section class="card"><h2>Auditoria e pedidos</h2><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Status</th><th>Total</th><th>Data</th><th>Ação</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id_pedido']?></td><td><?=h($o['cliente'])?></td><td><?=h($o['status'])?></td><td><?=dinheiro((float)$o['valor_total'])?></td><td><?=$o['data_criacao']?></td><td><?php if(in_array($o['status'],['pendente','em_separacao','aguardando_aprovacao'])):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="acao" value="cancelar"><input type="hidden" name="pedido" value="<?=$o['id_pedido']?>"><button>Cancelar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php $audit=db()->query('SELECT a.*,u.nome usuario FROM auditoria a LEFT JOIN usuarios u USING(id_usuario) ORDER BY criado_em DESC LIMIT 100')->fetchAll();?><h3>Histórico de alterações</h3><?php if(!$audit):?><p class="muted">Nenhum evento de auditoria registrado ainda.</p><?php endif;?><?php foreach($audit as $a):?><p><?=h($a['criado_em'].' · '.($a['usuario']??'Sistema').' · '.$a['acao'].' · '.$a['detalhes'])?></p><?php endforeach;?></section><section class="card" id="cupons"><div class="section-head"><h2>Cupons do mercado</h2><a class="button light" href="#novo-cupom">Adicionar cupom</a></div><form method="post" class="form" id="novo-cupom"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="acao" value="cupom"><div class="form-row"><label>Código<input name="codigo" maxlength="40" placeholder="ALVORADA10" pattern="[A-Za-z0-9_-]{3,40}" required></label><label>Nome da oferta<input name="titulo" maxlength="100" required></label></div><label>Descrição<textarea name="descricao" maxlength="255"></textarea></label><div class="form-row"><label>Tipo de desconto<select name="tipo"><option value="percentual">Porcentagem (%)</option><option value="fixo">Valor fixo (R$)</option></select></label><label>Valor do desconto<input name="valor" type="number" min="0.01" step="0.01" required></label></div><div class="form-row"><label>Pedido mínimo (R$)<input name="pedido_minimo" type="number" min="0" step="0.01" value="0"></label><label>Validade<input name="validade" type="date"></label></div><label>Limite de usos (opcional)<input name="limite_usos" type="number" min="1" placeholder="Sem limite"></label><button type="submit">Criar cupom</button></form><h3>Cupons cadastrados</h3><?php if(!$coupons):?><p class="muted">Nenhum cupom cadastrado ainda.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Código</th><th>Oferta</th><th>Desconto</th><th>Pedido mínimo</th><th>Validade</th><th>Usos</th><th>Status</th></tr></thead><tbody><?php foreach($coupons as $c):?><tr><td><strong><?=h($c['codigo'])?></strong></td><td><?=h($c['titulo'])?></td><td><?=$c['tipo']==='percentual'?rtrim(rtrim(number_format((float)$c['valor'],2,'.',''),'0'),'.').'%':dinheiro((float)$c['valor'])?></td><td><?=dinheiro((float)$c['pedido_minimo'])?></td><td><?=$c['validade']?date('d/m/Y',strtotime($c['validade'])):'Sem validade'?></td><td><?=$c['usos']?><?= $c['limite_usos']!==null?' / '.$c['limite_usos']:'' ?></td><td><?=($c['ativo']&&(!$c['validade']||$c['validade']>=date('Y-m-d')))?'Ativo':'Inativo'?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></main></body></html>
